-- ============================================================================
-- VENUE ADDRESSES
-- ============================================================================

ON CONFLICT (activity_id) DO UPDATE
  SET venue_name = EXCLUDED.venue_name,
      address_line1 = EXCLUDED.address_line1,
      city = EXCLUDED.city,
      province_or_state = EXCLUDED.province_or_state,
      country = EXCLUDED.country;

